From ff5cf6050ca26e7fbb88a87176136a0bb3b75c26 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:36:18 +0100
Subject: [PATCH] kcm: add a setting for AirPlay device discovery on PipeWire

Some distributions load PipeWire's RAOP discover module, which adds every
AirPlay device on the network as an output with no way to turn it off but
a config file. Offer a toggle that writes that file and restarts PipeWire.

BUG: 523215
---
 src/kcm/ui/main.qml   | 15 ++++++--
 src/modulemanager.cpp | 89 +++++++++++++++++++++++++++++++++++++++++++
 src/modulemanager.h   |  7 ++++
 3 files changed, 108 insertions(+), 3 deletions(-)

diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 140954d7..780adfdb 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -89,25 +89,34 @@ KCM.ScrollViewKCM {
         },
         Kirigami.Action {
             id: configureButton
-            visible: moduleManager.settingsSupported
-            enabled: moduleManager.configModuleLoaded
+            visible: moduleManager.settingsSupported || moduleManager.raopDiscoveryAvailable
+            enabled: moduleManager.configModuleLoaded || moduleManager.raopDiscoveryAvailable
             text: i18nd("kcm_pulseaudio", "Configure…")
             icon.name: "configure"

-            tooltip: i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName)
+            tooltip: moduleManager.settingsSupported ? i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName) : ""

             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Add virtual output device for simultaneous output on all local sound cards")
                 checkable: true
                 checked: moduleManager.combineSinks
                 onToggled: moduleManager.combineSinks = checked
             }
             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Automatically switch all running streams when a new output becomes available")
                 checkable: true
                 checked: moduleManager.switchOnConnect
                 onToggled: moduleManager.switchOnConnect = checked
             }
+            Kirigami.Action {
+                visible: moduleManager.raopDiscoveryAvailable
+                text: i18nd("kcm_pulseaudio", "Make AirPlay devices on the network available as outputs")
+                checkable: true
+                checked: moduleManager.raopDiscovery
+                onToggled: moduleManager.raopDiscovery = checked
+            }
         }
     ]

diff --git a/src/modulemanager.cpp b/src/modulemanager.cpp
index ffe98bb4..ea6c0bc2 100644
--- a/src/modulemanager.cpp
+++ b/src/modulemanager.cpp
@@ -9,13 +9,65 @@
 #include <PulseAudioQt/Module>
 #include <PulseAudioQt/Server>

+#include "debug.h"
 #include "gsettingsitem.h"
 #define PA_SETTINGS_PATH_MODULES "/org/freedesktop/pulseaudio/module-groups"

+#include <QDir>
+#include <QFile>
+#include <QProcess>
+#include <QStandardPaths>
 #include <QTimer>
 #include <chrono>

 using namespace std::chrono_literals;
+using namespace Qt::StringLiterals;
+
+namespace
+{
+inline QString pipeWireUserConfigDir()
+{
+    return QStandardPaths::writableLocation(QStandardPaths::GenericConfigLocation) + "/pipewire"_L1;
+}
+
+inline QString raopConfigPath()
+{
+    return pipeWireUserConfigDir() + "/pipewire.conf.d/00-plasma-pa-raop.conf"_L1;
+}
+
+// Distributions such as Fedora load the RAOP discover module from a pipewire.conf.d fragment,
+// others ship it disabled, so only offer the setting when some config file loads it.
+bool raopDiscoverConfigured()
+{
+    QStringList dirs = {pipeWireUserConfigDir(), u"/etc/pipewire"_s};
+    const auto dataDirs = QStandardPaths::standardLocations(QStandardPaths::GenericDataLocation);
+    for (const QString &dataDir : dataDirs) {
+        dirs.append(dataDir + "/pipewire"_L1);
+    }
+
+    for (const QString &dir : std::as_const(dirs)) {
+        QStringList files = {dir + "/pipewire.conf"_L1};
+        const auto fragments = QDir(dir + "/pipewire.conf.d"_L1).entryInfoList({u"*.conf"_s}, QDir::Files | QDir::Readable);
+        for (const QFileInfo &fragment : fragments) {
+            files.append(fragment.filePath());
+        }
+
+        for (const QString &path : std::as_const(files)) {
+            QFile file(path);
+            if (!file.open(QFile::ReadOnly)) {
+                continue;
+            }
+            while (!file.atEnd()) {
+                const QByteArray line = file.readLine().trimmed();
+                if (!line.startsWith('#') && line.contains("libpipewire-module-raop-discover")) {
+                    return true;
+                }
+            }
+        }
+    }
+    return false;
+}
+} // namespace

 namespace PulseAudioQt
 {
@@ -67,6 +119,7 @@ ModuleManager::ModuleManager(QObject *parent)
     connect(m_deviceManager, &ConfigModule::subtreeChanged, this, &ModuleManager::switchOnConnectChanged);

     connect(Context::instance()->server(), &Server::updated, this, &ModuleManager::serverUpdated);
+    connect(Context::instance()->server(), &Server::updated, this, &ModuleManager::raopDiscoveryChanged);

     auto *updateModulesTimer = new QTimer(this);
     updateModulesTimer->setInterval(500ms);
@@ -75,6 +128,8 @@ ModuleManager::ModuleManager(QObject *parent)
     connect(Context::instance(), &Context::moduleAdded, updateModulesTimer, static_cast<void (QTimer::*)(void)>(&QTimer::start));
     connect(Context::instance(), &Context::moduleRemoved, updateModulesTimer, static_cast<void (QTimer::*)(void)>(&QTimer::start));
     updateLoadedModules();
+
+    m_raopDiscoverConfigured = raopDiscoverConfigured();
 }

 ModuleManager::~ModuleManager() = default;
@@ -138,6 +193,40 @@ QString ModuleManager::configModuleName() const
 {
     return QStringLiteral("module-gsettings");
 }
+
+bool ModuleManager::raopDiscoveryAvailable() const
+{
+    return Context::instance()->server()->isPipeWire() && m_raopDiscoverConfigured;
+}
+
+bool ModuleManager::raopDiscovery() const
+{
+    return !QFile::exists(raopConfigPath());
+}
+
+void ModuleManager::setRaopDiscovery(bool raopDiscovery)
+{
+    if (raopDiscovery == this->raopDiscovery()) {
+        return;
+    }
+
+    if (raopDiscovery) {
+        QFile::remove(raopConfigPath());
+    } else {
+        QDir().mkpath(QFileInfo(raopConfigPath()).path());
+        QFile file(raopConfigPath());
+        if (!file.open(QFile::WriteOnly | QFile::Truncate)) {
+            qCWarning(PLASMAPA) << "Failed to open file for writing" << file.fileName() << file.errorString();
+            return;
+        }
+        file.write("context.properties = {\n    module.raop = false\n}\n");
+    }
+    Q_EMIT raopDiscoveryChanged();
+
+    auto systemctl = new QProcess(this);
+    connect(systemctl, &QProcess::finished, systemctl, &QObject::deleteLater);
+    systemctl->start(u"systemctl"_s, {u"--user"_s, u"restart"_s, u"wireplumber.service"_s, u"pipewire.service"_s});
+}
 }

 #include "moc_modulemanager.cpp"
diff --git a/src/modulemanager.h b/src/modulemanager.h
index 6241f093..93bd9484 100644
--- a/src/modulemanager.h
+++ b/src/modulemanager.h
@@ -30,6 +30,8 @@ class ModuleManager : public QObject
     Q_PROPERTY(bool configModuleLoaded READ configModuleLoaded NOTIFY loadedModulesChanged)
     Q_PROPERTY(QString configModuleName READ configModuleName CONSTANT)
     Q_PROPERTY(QStringList loadedModules READ loadedModules NOTIFY loadedModulesChanged)
+    Q_PROPERTY(bool raopDiscoveryAvailable READ raopDiscoveryAvailable NOTIFY raopDiscoveryChanged)
+    Q_PROPERTY(bool raopDiscovery READ raopDiscovery WRITE setRaopDiscovery NOTIFY raopDiscoveryChanged)
 public:
     explicit ModuleManager(QObject *parent = nullptr);
     ~ModuleManager() override;
@@ -42,12 +44,16 @@ public:
     QStringList loadedModules() const;
     bool configModuleLoaded() const;
     QString configModuleName() const;
+    bool raopDiscoveryAvailable() const;
+    bool raopDiscovery() const;
+    void setRaopDiscovery(bool raopDiscovery);

 Q_SIGNALS:
     void combineSinksChanged();
     void switchOnConnectChanged();
     void loadedModulesChanged();
     void serverUpdated();
+    void raopDiscoveryChanged();

 private:
     void updateLoadedModules();
@@ -56,6 +62,7 @@ private:
     ConfigModule *m_switchOnConnect;
     ConfigModule *m_deviceManager;
     QStringList m_loadedModules;
+    bool m_raopDiscoverConfigured;
 };

 } // PulseAudioQt
